import math

def _get_joints(agent_components):
    if isinstance(agent_components, dict):
        return agent_components.get("joints", [])
    return []

def build_agent(sandbox):
    # Torso: lightweight, low center of mass
    torso = sandbox.add_beam(x=10.0, y=2.5, width=1.0, height=0.5, density=1.0)

    # Wheels: two wheels with moderate radius and low density
    wheel_radius = 0.2
    wheel1 = sandbox.add_wheel(x=8.0, y=1.2, radius=wheel_radius, density=0.5)
    wheel2 = sandbox.add_wheel(x=12.0, y=1.2, radius=wheel_radius, density=0.5)

    # Joints: pivot joints connecting torso to wheels
    joint1 = sandbox.add_joint(torso, wheel1, (8.0, 1.2), type='pivot')
    joint2 = sandbox.add_joint(torso, wheel2, (12.0, 1.2), type='pivot')

    # Material properties: low friction to prevent wheel spin-up
    sandbox.set_material_properties(torso, restitution=0.1, friction=0.5)
    sandbox.set_material_properties(wheel1, restitution=0.1, friction=0.2)
    sandbox.set_material_properties(wheel2, restitution=0.1, friction=0.2)

    return {"body": torso, "joints": [joint1, joint2]}

def agent_action(sandbox, agent_body, step_count):
    joints = _get_joints(agent_body)
    torso = agent_body.get("body") if isinstance(agent_body, dict) else None

    if torso is not None and torso.position.x > 28.0:
        rotation_speed = 0.0
    else:
        # Positive rotation to drive forward
        rotation_speed = 10.0

    for j in joints:
        sandbox.set_motor(j, rotation_speed, max_torque=100.0)

